alter table public.partidas_obra add column if not exists fecha_inicio date, add column if not exists fecha_termino date; comment on column public.partidas_obra.fecha_inicio is 'Inicio programado persistente para Curva S y valor planificado.'; comment on column public.partidas_obra.fecha_termino is 'Término programado persistente para Curva S y valor planificado.'; create index if not exists idx_partidas_obra_fechas_programadas on public.partidas_obra (obra_nombre, fecha_inicio, fecha_termino);;
